[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-01)" = 'reminder to x: aoi 2026-01-01 10:00-11:00' ] || { echo "a day with a booking should print a reminder"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
[ -z "$(bash src/remind.sh 2>/dev/null)" ] || { echo "usage should go to stderr, not stdout"; fail=1; }
BOOKINGS=/nonexistent/bookings.tsv bash src/remind.sh 2026-01-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a missing bookings file should exit 2"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check 2>&1 | tail -3; bash tools/lint | tail -1; git diff --stat; gh label list --limit 100 2>&1 | grep -i -E "needs|state:|qm-blocked|dev-done"

