#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/list.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list sorted"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
rm -f "$t"; exit $fail

spec/remind.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'no bookings: 2026-01-02' ] || { echo "a day without bookings"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-01)" = 'reminder to x: aoi 2026-01-01 10:00-11:00' ] || { echo "a day with a booking should print a reminder"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
[ -z "$(bash src/remind.sh 2>/dev/null)" ] || { echo "usage should go to stderr, not stdout"; fail=1; }
BOOKINGS=/nonexistent/bookings.tsv bash src/remind.sh 2026-01-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a missing bookings file should exit 2"; fail=1; }
rm -f "$t"; exit $fail

